UPDATE wa_group wa_group INNER JOIN ( SELECT DISTINCT deleted_link.tenant_id, deleted_link.group_id FROM group_link deleted_link WHERE deleted_link.tenant_id = #{tenantId} AND deleted_link.id IN
#{groupLinkId}
AND deleted_link.group_id IS NOT NULL ) deleted_alias ON deleted_alias.tenant_id = wa_group.tenant_id AND deleted_alias.group_id = wa_group.id SET wa_group.deleted_at = #{deletedAt}, wa_group.updated_at = GREATEST(wa_group.updated_at, #{deletedAt}) WHERE wa_group.tenant_id = #{tenantId} AND wa_group.deleted_at IS NULL AND NOT EXISTS ( SELECT 1 FROM group_link active_link WHERE active_link.tenant_id = wa_group.tenant_id AND active_link.deleted_at IS NULL AND active_link.group_id = wa_group.id )

UPDATE wa_group wa_group INNER JOIN ( SELECT DISTINCT deleted_link.tenant_id, deleted_link.group_id FROM group_link deleted_link WHERE deleted_link.tenant_id = #{tenantId} AND deleted_link.label_id IN
#{labelId}
AND deleted_link.group_id IS NOT NULL ) deleted_alias ON deleted_alias.tenant_id = wa_group.tenant_id AND deleted_alias.group_id = wa_group.id SET wa_group.deleted_at = #{deletedAt}, wa_group.updated_at = GREATEST(wa_group.updated_at, #{deletedAt}) WHERE wa_group.tenant_id = #{tenantId} AND wa_group.deleted_at IS NULL AND NOT EXISTS ( SELECT 1 FROM group_link active_link WHERE active_link.tenant_id = wa_group.tenant_id AND active_link.deleted_at IS NULL AND active_link.group_id = wa_group.id )

